import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/The-pspp_002doutput-convert-Command.md","filePath":"manual-en/The-pspp_002doutput-convert-Command.md","lastUpdated":1785684581000}'),i={name:"manual-en/The-pspp_002doutput-convert-Command.md"};function p(s,e,r,d,f,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h3 id="_19-3-the-convert-command" tabindex="-1">19.3 The <code>convert</code> Command <a class="header-anchor" href="#_19-3-the-convert-command" aria-label="Permalink to &quot;19.3 The `convert` Command&quot;">​</a></h3><pre><code>pspp-output [options] convert source destination\n</code></pre><p>Reads SPV file source and converts it to another format, writing the output to destination.</p><p>By default, the intended format for destination is inferred based on its extension, in the same way that the <code>pspp</code> program does for its output files. See <a href="./Invoking-PSPP">Invoking PSPP</a>, for details.</p><p>See <a href="./Input-Selection-Options">Input Selection Options</a>, for information on the options available to select a subset of objects to include in the output. The following additional options are accepted:</p><p>-O format=format</p><p>Overrides the format inferred from the output file’s extension. Use --help to list the available formats. See <a href="./Invoking-PSPP">Invoking PSPP</a>, for details of the available output formats.</p><p>-O option=value</p><p>Sets an option for the output file format. See <a href="./Invoking-PSPP">Invoking PSPP</a>, for details of the available output options.</p><p>-F --force</p><p>By default, if the source is corrupt or otherwise cannot be processed, the destination is not written. With -F or --force, the destination is written as best it can, even with errors.</p><p>--table-look=file</p><p>Reads a table style from file and applies it to all of the output tables. The file should be a TableLook .stt or .tlo file.</p><p>--use-page-setup</p><p>By default, the <code>convert</code> command uses the default page setup (for example, page size and margins) for destination, or the one specified with -O options, if any. Specify this option to ignore these sources of page setup in favor of the one embedded in the SPV, if any.</p>',15)])])}const h=t(i,[["render",p]]);export{c as __pageData,h as default};
